24	// quotedSegments extracts every bracketed JSON-string segment ("...") from a
25	// rendered location, honoring backslash escapes while scanning.
26	func quotedSegments(t *testing.T, path string) []string {
27		t.Helper()
28		var segs []string
29		rest := path
30		for {
31			open := strings.Index(rest, "[\"")
32			if open < 0 {
33				return segs
34			}
35			j := open + 2
36			for j < len(rest) {
37				if rest[j] == '\\' {
38					j += 2
39					continue
40				}
41				if rest[j] == '"' && j+1 < len(rest) && rest[j+1] == ']' {
42					break
43				}
44				j++
45			}
46			if j >= len(rest) {
47				t.Fatalf("unterminated quoted segment in path %q", path)
48			}
49			segs = append(segs, rest[open+1:j+1])
50			rest = rest[j+2:]
51		}
52	}
