54	// decodeSegment JSON-decodes one quoted path segment back to its member name.
55	func decodeSegment(t *testing.T, seg string) string {
56		t.Helper()
57		var name string
58		if err := json.Unmarshal([]byte(seg), &name); err != nil {
59			t.Fatalf("segment %q is not a decodable JSON string: %v", seg, err)
60		}
