69		for r := rune(0); r <= 0xA0; r++ {
70			key := "meta" + string(r) + "info"
71			enc := jsonEncodePathString(key)
72			if strings.Contains(enc, `\x`) {
73				t.Fatalf("U+%04X produced JSON-illegal \\xNN spelling: %s", r, enc)
74			}
75			assertNoControlEffect(t, enc)
76			if got := decodeSegment(t, enc); got != key {
77				t.Fatalf("U+%04X round trip = %q, want %q (encoded %s)", r, got, key, enc)
78			}
79		}
80		// The C1 range including NEL (U+0085), DEL, and the line separators all
81		// keep the \uXXXX spelling, while visible characters (including CJK and
82		// HTML-significant ones, which keep encoding/json's HTML escaping) decode
83		// back exactly.
84		for _, r := range []rune{0x7f, 0x80, 0x85, 0x9f, 0x2028, 0x2029, '"', '\\', '\n', '<', '>', '&', '名', '😀'} {
