100		}
101		if control != `"\u0085"` {
102			t.Fatalf("U+0085 encoding = %s, want \"\\u0085\"", control)
103		}
104		if literal != `"\\u0085"` {
105			t.Fatalf("literal text encoding = %s, want \"\\\\u0085\"", literal)
106		}
107		if got := decodeSegment(t, literal); got != `\u0085` {
108			t.Fatalf("literal text round trip = %q", got)
109		}
110		// The empty name keeps its established spelling.
111		if got := jsonEncodePathString(""); got != `""` {
112			t.Fatalf("empty name encoded as %s", got)
113		}
