145				wantPath:  `$["meta\u007finfo"]`,
146			},
147			{
148				name:      "escaped DEL name",
149				body:      base + `,"meta\u007finfo":{"x":1,"x":2}`,
150				wantField: "x",
151				wantPath:  `$["meta\u007finfo"]`,
152			},
153			{
154				name:      "first C1 control U+0080",
155				body:      base + `,"a\u0080b":{"x":1,"x":2}`,
156				wantField: "x",
157				wantPath:  `$["a\u0080b"]`,
158			},
