161				body:      base + `,"a\u009fb":{"x":1,"x":2}`,
162				wantField: "x",
163				wantPath:  `$["a\u009fb"]`,
164			},
165			{
166				name:      "nested object under a control-character name",
167				body:      base + `,"a\u0085b":{"c\u007fd":{"x":1,"x":2}}`,
168				wantField: "x",
169				wantPath:  `$["a\u0085b"]["c\u007fd"]`,
170			},
