231	// TestParse_TextErrorPathsWithControlCharacterNames checks the
232	// invalid-UTF-8 and unpaired-surrogate verdicts: a problem in a member value
233	// under a control-character name reaches into the object with the member
234	// segment, while a problem inside the member name itself points at the
235	// owning object. Arrays keep their real zero-based index.
236	func TestParse_TextErrorPathsWithControlCharacterNames(t *testing.T) {
237		base := `"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[]`
238		litName := `"meta` + "\u0085" + `info"` // member name written with raw NEL
239		escName := `"meta\u0085info"`           // same name written with the escape
240		t.Run("invalid UTF-8 in nested value", func(t *testing.T) {
241			for _, name := range []string{litName, escName} {
242				doc := `{` + base + `,` + name + `:{"note":"a` + badUTF8 + `"}}`
243				err := parseTextErr(t, doc)
244				e, ok := err.(*invalidUTF8Error)
245				if !ok {
246					t.Fatalf("expected *invalidUTF8Error, got %T: %v", err, err)
247				}
248				if e.isKey || e.path != `$["meta\u0085info"].note` {
249					t.Fatalf("path=%q isKey=%v, want $[\"meta\\u0085info\"].note value", e.path, e.isKey)
250				}
251				assertNoControlEffect(t, err.Error())
252			}
253		})
254		t.Run("unpaired surrogate in nested value", func(t *testing.T) {
255			for _, name := range []string{litName, escName} {
256				doc := `{` + base + `,` + name + `:{"note":"\uD800"}}`
257				err := parseTextErr(t, doc)
258				e, ok := err.(*unpairedSurrogateError)
259				if !ok {
260					t.Fatalf("expected *unpairedSurrogateError, got %T: %v", err, err)
261				}
262				if e.isKey || e.path != `$["meta\u0085info"].note` {
263					t.Fatalf("path=%q isKey=%v, want $[\"meta\\u0085info\"].note value", e.path, e.isKey)
264				}
265				assertNoControlEffect(t, err.Error())
266			}
267		})
268		t.Run("invalid UTF-8 in member name points at owner", func(t *testing.T) {
269			doc := `{` + base + `,` + `"meta` + "\u0085" + `in` + badUTF8 + `fo":1}`
270			err := parseTextErr(t, doc)
271			e, ok := err.(*invalidUTF8Error)
272			if !ok || !e.isKey || e.path != "$" {
273				t.Fatalf("got %T path=%q isKey=%v, want key error at $", err, ePath(err), eIsKey(err))
274			}
275		})
276		t.Run("unpaired surrogate in member name points at owner", func(t *testing.T) {
277			doc := `{` + base + `,"meta\u0085in\uD800fo":1}`
278			err := parseTextErr(t, doc)
279			e, ok := err.(*unpairedSurrogateError)
280			if !ok || !e.isKey || e.path != "$" {
281				t.Fatalf("got %T path=%q isKey=%v, want key error at $", err, ePath(err), eIsKey(err))
282			}
283		})
284		t.Run("array item under control-character name keeps real index", func(t *testing.T) {
285			doc := `{` + base + `,` + escName + `:["ok","\uDC00"]}`
286			err := parseTextErr(t, doc)
287			e, ok := err.(*unpairedSurrogateError)
288			if !ok || e.isKey || e.path != `$["meta\u0085info"][1]` {
289				t.Fatalf("got %T path=%q isKey=%v, want value at index 1", err, ePath(err), eIsKey(err))
290			}
291			assertNoControlEffect(t, err.Error())
292		})
293	}
294	
295	func ePath(err error) string {
296		switch e := err.(type) {
297		case *invalidUTF8Error:
298			return e.path
299		case *unpairedSurrogateError:
300			return e.path
301		}
302		return ""
303	}
304	
305	func eIsKey(err error) bool {
306		switch e := err.(type) {
307		case *invalidUTF8Error:
308			return e.isKey
309		case *unpairedSurrogateError:
310			return e.isKey
311		}
312		return false
313	}
314	
315	// TestParse_ControlNamePathSegmentsDecodeBack takes the reported locations
316	// apart and proves every quoted segment restores the exact decoded member
317	// name — the raw control character — while the plain text "\u0085" (a
318	// backslash followed by u0085) restores to those six ordinary characters
319	// instead, so the two stay distinguishable.
320	func TestParse_ControlNamePathSegmentsDecodeBack(t *testing.T) {
321		base := `"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[]`
322		cases := []struct {
323			body     string
324			wantSegs []string
325		}{
326			{
327				body:     base + `,"meta` + "\u0085" + `info":{"x":1,"x":2}`,
328				wantSegs: []string{"meta\u0085info"},
329			},
330			{
331				body:     base + `,"meta\u007finfo":{"x":1,"x":2}`,
332				wantSegs: []string{"meta\u007finfo"},
333			},
334			{
335				body:     base + `,"a\u0085b":{"c\u009fd":{"x":1,"x":2}}`,
336				wantSegs: []string{"a\u0085b", "c\u009fd"},
337			},
338			{
339				// A real backslash then "u0085" is ordinary text: the decoded
340				// segment contains the backslash, not the control character.
341				body:     base + `,"meta\\u0085info":{"x":1,"x":2}`,
342				wantSegs: []string{`meta\u0085info`},
343			},
344		}
345		for i, tc := range cases {
346			err := parseDupErr(t, "{"+tc.body+"}")
347			dme := err.(*duplicateMemberError)
348			segs := quotedSegments(t, dme.path)
349			if len(segs) != len(tc.wantSegs) {
350				t.Fatalf("case %d: got %d segments %q, want %d (path %s)",
351					i, len(segs), segs, len(tc.wantSegs), dme.path)
352			}
353			for j, seg := range segs {
354				if got := decodeSegment(t, seg); got != tc.wantSegs[j] {
355					t.Fatalf("case %d segment %d: decoded %q, want %q", i, j, got, tc.wantSegs[j])
356				}
357			}
358			assertNoControlEffect(t, dme.path)
359		}
360	}
361	
362	// TestParse_ControlNamePathSameForEquivalentSpellings ensures the two
363	// spellings of one legal member name — raw DEL/C1 character versus its
364	// \uXXXX escape — always render the exact same location.
365	func TestParse_ControlNamePathSameForEquivalentSpellings(t *testing.T) {
366		base := `"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[]`
367		for _, r := range []rune{0x7f, 0x80, 0x85, 0x9f} {
368			literal := `{` + base + `,"meta` + string(r) + `info":{"x":1,"x":2}}`
369			escaped := `{` + base + fmt.Sprintf(`,"meta\u%04xinfo":{"x":1,"x":2}}`, r)
370			litErr := parseDupErr(t, literal).(*duplicateMemberError)
371			escErr := parseDupErr(t, escaped).(*duplicateMemberError)
372			if litErr.path != escErr.path {
373				t.Fatalf("U+%04X: paths differ: %q vs %q", r, litErr.path, escErr.path)
374			}
375		}
376	}
377	
378	// TestParse_ControlCharacterNamesLegalWhenDistinct verifies that member
379	// names containing DEL or C1 controls are accepted, kept and ignored as
380	// unknown fields when there is no error, and the plan is unaffected.
381	func TestParse_ControlCharacterNamesLegalWhenDistinct(t *testing.T) {
382		raw := `{
383			"app": "a", "revision": "r", "image": "i", "batchSize": 2,
384			"clusters": [{"id": "c1"}, {"id": "c2"}],
385			"meta\u007fextra": {"x": 1},
386			"meta` + "\u0085" + `info": {"note": "ok"},
387			"a\u009fb": "v",
388			"ls\u2028end": 1
389		}`
390		in, err := ParseReleaseInput([]byte(raw))
391		if err != nil {
392			t.Fatalf("legal control-character member names must be accepted: %v", err)
393		}
394		plan, err := MakeReleasePlan(in)
395		if err != nil {
396			t.Fatalf("plan failed: %v", err)
397		}
398		if len(plan.Batches) != 1 || strings.Join(plan.Batches[0].Clusters, ",") != "c1,c2" {
399			t.Fatalf("unexpected plan: %+v", plan.Batches)
400		}
401	}
402	
403	// TestPlanCLI_ControlCharacterNameDuplicateFailsCleanly drives the CLI with
404	// the issue's document: exit code 1, empty stdout, and stderr naming the
405	// duplicated member "x" and the readable, escaped object position.
406	func TestPlanCLI_ControlCharacterNameDuplicateFailsCleanly(t *testing.T) {
407		if _, err := exec.LookPath("go"); err != nil {
408			t.Skip("go toolchain unavailable")
409		}
410		dir := t.TempDir()
411		path := filepath.Join(dir, "plan.json")
412		doc := `{
413			"app": "payments", "revision": "v1", "image": "img",
414			"batchSize": 1, "clusters": [],
415			"meta\u0085info": {"x": 1, "x": 2}
416		}`
417		if err := os.WriteFile(path, []byte(doc), 0o644); err != nil {
418			t.Fatal(err)
419		}
420		code, stdout, stderr := runCLI(t, "plan", path)
421		if code != 1 {
422			t.Fatalf("expected exit code 1, got %d; stdout=%q stderr=%q", code, stdout, stderr)
423		}
424		if stdout != "" {
425			t.Fatalf("expected empty stdout, got %q", stdout)
426		}
427		if !strings.Contains(stderr, `"x"`) || !strings.Contains(stderr, `$["meta\u0085info"]`) {
428			t.Fatalf("stderr should name field and escaped position, got %q", stderr)
429		}
430		assertNoControlEffect(t, stderr)
431		if strings.Contains(stderr, `\x`) {
432			t.Fatalf("stderr must not contain a \\xNN escape: %q", stderr)
433		}
434	}
