				// spelling decodes back to the character itself and is
				// distinct from ordinary text containing "\u007f"; no
				// JSON-illegal \xNN form is ever emitted.
				fmt.Fprintf(&b, `\u%04x`, r)
			default:
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
