	if got := quoteReportText.render(real); got != `"c-a\nc-b"` {
		t.Errorf("real newline report spelling = %q", got)
	}
	if got := quoteReportText.render(literal); got != `"c-a\\nc-b"` {
		t.Errorf("literal \\n report spelling = %q", got)
	}
}

